INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('2TBXnDeMk6lX3q7JBVTU', 'qna', 'ഒരു കള്ളനെ പോലീസ് ഓടിക്കുകയായിരുന്നു. അങ്ങനെ ഓടിച്ചെന്ന് കള്ളൻ ഒരു സ്ഥലത്ത് എത്തിയപ്പോൾ വഴി അടഞ്ഞുപോയി. മൂന്ന് വഴികളും ബ്ലോക്ക് ആയിരുന്നു, പിന്നിൽ പോലീസും ഉണ്ടായിരുന്നു. കള്ളന്റെ കയ്യിൽ ഒരു പാത്രമുണ്ടായിരുന്നു. അവന് നല്ല ദാഹവുമുണ്ടായിരുന്നു, ഒപ്പം പോലീസിന്റെ പിടിയിൽ നിന്ന് രക്ഷപ്പെടുകയും വേണം. അങ്ങനെയെങ്കിൽ, കള്ളൻ എങ്ങനെയാണ് രക്ഷപ്പെട്ടത്?', 'കള്ളൻ ആ പാത്രം എടുത്ത്  "കമത്തി" എന്നിട്ട് അതിനുള്ളിലെ മാ (Juice) എടുത്തു കുടിച്ചു. ബാക്കി വന്ന ''കത്തി'' എടുത്ത് പോലീസിനെ കുത്തിയിട്ട് രക്ഷപ്പെട്ടു! 🔥', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788459571/malayalam-joke-app/ibx29my8as4vu9v9cwb4.png', 'malayalam-joke-app/ibx29my8as4vu9v9cwb4', 5, 3, 'quarantine', 'anonymous', NULL, 1788459576501, 1788459576501);
