INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('2bPCfkvcCeyiPuBseCUs', 'qna', 'ഒരാൾ മരുഭൂമിയിൽ കുടുങ്ങിപ്പോയി. അയാളുടെ കൈയിലുള്ളത് ആകെ ഒരു ഗൺ മാത്രം അയാൾ എങ്ങനെ രക്ഷപ്പെടും', 'അയാൾ ഗൺ വെടിവെക്കും അപ്പോൾ വരുന്നത് ബുള്ളറ്റ് ആണ് ആ ബുള്ളറ്റിൽ അയാൾ കയറിപ്പോകും', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1789039183/malayalam-joke-app/ouogpnlevnatlkjt6ptt.jpg', 'malayalam-joke-app/ouogpnlevnatlkjt6ptt', 5, 0, 'quarantine', 'anonymous', NULL, 1789039185240, 1789039185240);
