INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('2gaMB0uC9j7wwEA8KmcR', 'qna', 'ഉറുമ്പും തിമിംഗലവും അടിയിട്ടു അതിൽ ഉറുമ്പ് ജയിച്ചു. കാരണമെന്ത്', 'ഉറുമ്പ് sunscreen ഇട്ടേപു ഉണ്ടായിരുന്നു, അതുകൊണ്ട് veyil(sunlight)അടിച്ചാലും കുഴപ്പമില്ലലോ', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1789305103097, 1789305103097);
