INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('3O5Q4kfdc2DlKnrfHUma', 'qna', 'ഒരാൾ കടയിൽ പോയിട്ട് കടക്കാരനോട് രണ്ടു സാധനങ്ങൾ ആവശ്യപ്പെട്ടു. അത് കേട്ടപാടെ കടക്കാരൻ ഇറങ്ങി ഓടി. എന്തുകൊണ്ടായിരിക്കും?', 'രണ്ടു മുട്ടയും🍒 അരിയും🔪', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788541743152, 1788541743152);
