INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('3SNe29h7AMF44Wx1CMVb', 'qna', 'ഒരിടത്ത് രാമു എന്ന് പേരുള്ള ആൾ ഉണ്ടായിരുന്നു. അയാൾ ഒരു ജോലിയും ചെയ്യില്ല. കുറേ മണ്ടത്തരം കാണിക്കും. അയാൾക്ക് അത്കൊണ്ട് എന്നും നാട്ടുകാരുടെ കയ്യിൽ നിന്നും തല്ലും കൊള്ളും. പക്ഷെ വൈകിട്ട് വീട്ടിൽ തിരിച്ചു എത്തുമ്പോൾ രാമുവിൻറെ കയ്യിൽ നിറയെ പൈസ കാണും. എങ്ങനെ?', 'രാമു ഇടികൊണ്ട് കണ്ണീന്ന് പൊന്നീച്ച പറക്കും. എന്നട്ട് ആ പൊന്നീച്ചയെ വിറ്റ് cash ആക്കും.', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788690504/malayalam-joke-app/bwzlhi72rksvjaiiewkt.png', 'malayalam-joke-app/bwzlhi72rksvjaiiewkt', 96, 82, 'active', 'anonymous', 0.42732631291047218, 1788690505843, 1788690505843);
