INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('3t4Kzou1pe2crfKp3V8X', 'qna', 'ഒരു രാജാവിന് മൂന്ന് പെൺമക്കളുണ്ടായിരുന്നു, മൂത്ത മകൾ ''an'' മകൾ ''or'' ഇളയ മകൾ ''if'' എന്നായിരുന്നു അവരുടെ പെരുക്കൾ.ഒരു ദിവസം ഒരു കൊലയാളി തന്റെ പെൺമക്കളെ വെടിവച്ചു.മൂത്ത മകളും ഇളയ മകളും മരിച്ചു, പക്ഷേ രണ്ടാമത്തെ മകൾ രക്ഷപ്പെട്ടു. എങ്ങനെ?', 'ഓർമ്മകൾ മരിക്കുന്നില്ല 🙌', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788533825972, 1788533825972);
