INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('89X1Xo7SH5mgVvFSOMWj', 'qna', 'രണ്ട് പൊട്ടന്മാർ നടന്ന് പോകുകയായിരുന്നു. അതിൽ ഒരു പൊട്ടന്റെ കയ്യിൽ റേഡിയോ ഉണ്ടായിരുന്നു. റേഡിയോ കയ്യിലുള്ള പൊട്ടൻ കിണറ്റിൽ ചാടിപ്പോയി. അപ്പോൾ മുകളിൽ നിൽക്കുന്ന പൊട്ടൻ താഴെ നിൽക്കുന്ന പൊട്ടനെ എങ്ങനെ രക്ഷിക്കും?', 'കിണറ്റിൽ പോയ പൊട്ടൻ റേഡിയോയിൽ പാട്ട് വെക്കും. ആ പാട്ടിനനുസരിച്ച് മുകളിൽ നിൽക്കുന്ന പൊട്ടൻ ഡാൻസ് സ്റ്റെപ്പ് ഇടും. ഈ സ്റ്റെപ്പ് കയറി കയറി താഴെ നിൽക്കുന്ന പൊട്ടൻ മുകളിലെത്തും.', NULL, NULL, 5, 0, 'deleted', 'anonymous', NULL, 1788461647113, 1788461647113);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('89vkJhLrHOFnsbJ9yX6W', 'qna', 'ഈഗിൾ ഗെയിമിംഗ് ഒരു ദിവസം മീൻ പിടിക്കാൻ പോയി പക്ഷേ എങ്ങനെ മീൻ പിടിക്കും ചൂണ്ട എടുത്തിട്ടില്ല അതിൽ കോർക്കുന്ന നൂൽ എടുത്തിട്ടില്ല തീറ്റ എടുത്തിട്ടില്ല അപ്പോൾ എങ്ങനെ മീൻ പിടിക്കും', 'ഈഗിൾ ഗെയിമിലെ ഈഗിളിനെ വിളിക്കും ശേഷം പറയും മീൻ പിടിക്കാൻ', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788513482467, 1788513482467);
