INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('CqFPCkYSt5d0cPRL33Sr', 'qna', 'സുരേഷ് വഴിയിലൂടെ പോകുമ്പോൾ ഒരു 2000 രൂപാ നോട്ടും ഒരു ഉണക്കമീനും കിടക്കുന്നത് കണ്ടു. സുരേഷ് ഉണക്കമീൻ എടുത്ത് 2000 രൂപ അവിടെത്തന്നെ ഇട്ടു. എന്തുകൊണ്ട്? 😄', 'സുരേഷ് ഒരു പൂച്ച ആയിരുന്നു.🐱😂', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1789121461976, 1789121461976);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('CsH5AZwWMTsESwq98ptD', 'qna', 'Oru divasam vettakkaran kaaatil vettakk pooyi appol ayal oru elephantine kandu athine shoot cheyithu. But avide dead aayath oru parrot aayirunnu. Engane?', 'Aah elephantinte peru "parrot"ennayirunnu.🤣', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788634051268, 1788634051268);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('CsyZFd7Xii0zu4OLspVA', 'qna', 'ഒരു സിംഹം അതെ പോലെ പുലി ഒരു മാനും ഓട്ടക്കമത്സരം വച്ചു പക്ഷെ മാന് ജയിച്ചു why?', 'വേറെ ഒന്നുമല്ല മാനാണ് ആദ്യം എത്തിയത് അതോണ്ട്', NULL, NULL, 76, 66, 'active', 'anonymous', 0.77785929375936280, 1788455788600, 1788455788600);
