INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('Czhgn4RLuk2PtNf4wWl6', 'qna', 'ആമയുടെയും മുയലിൻറെയും ഓട്ടമത്സരം കഥയിൽ ശെരിക്കും മുയലാണ് ജയിക്കുന്നത്. പക്ഷെ മുയലിനെ തോൽപ്പിച്ച് ആമയെ ജയിപ്പിച്ചു. കാരണമെന്ത്?', 'ആ മത്സരത്തിന്റെ റഫറി ഒരു തമിഴനായിരുന്നു. പുള്ളിയോട് മുയലല്ലേ ജയിച്ചതെന്ന് ചോദിച്ചപ്പോ പുള്ളി ''ആമാ'' എന്ന് പറഞ്ഞു😶‍🌫️.', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788541002027, 1788541002027);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('D3jJVdJtr5eWEub0SvK7', 'single', 'ഈ നാട്ടിൽ തമ്പുരാന്മാർ ഉണ്ടായത് എങ്ങനെ ആണെന്ന് അറിയോ? പണ്ട് പണ്ടൊരാൾ redbull can തള്ളവിരൽ കൊണ്ട് ഞെക്കി പൊട്ടിക്കാൻ നോക്കി വിരൽ അതിൽ കുടിങ്ങി. ഊരാൻ പറ്റാതെ വന്നപ്പോ നേരെ അടുത്തുള്ള ഡോക്ടർടേ വീട്ടിലേക്ക് പോയി കതകിൽ മുട്ടി. ഡോക്ടർ അകത്തുനിന്ന് "ആരാ എന്താ "എന്ന് ചോദിച്ചപ്പോ "തമ്പ് ഊരാൻ ആണേ " എന്ന് മറുപടി വന്നു. ഡോക്ടർ കേട്ടത് തമ്പുരാൻ ആണേ എന്ന്. അങ്ങനെ അയാളെ എല്ലാരും തമ്പുരാൻ എന്ന് വിളിക്കാൻ തുടങ്ങി അയാളുടെ തലമുറ പിന്നീട് തമ്പുരാക്കന്മാർ എന്നറിയപ്പെടാൻ തുടങ്ങി', NULL, 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1789280930/malayalam-joke-app/uryfhto82fe7ehx8c7ct.jpg', 'malayalam-joke-app/uryfhto82fe7ehx8c7ct', 5, 0, 'quarantine', 'anonymous', NULL, 1789280931439, 1789280931439);
