INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('KZFqsArox9u8wizZjRPM', 'qna', 'ഡൽഹിക്കാരൻ കേരളത്തിൽ കട തുറന്നു.മലയാളി ചിക്കൻ ഓർഡർ ചെയ്തു. നേരം വൈകിയിട്ടും ഡെലിവറി വന്നില്ല. വിളിച്ചപ്പോൾ കൊണ്ട് വരാമെന്നു പറഞ്ഞു.വന്നില്ല.വീണ്ടും വിളിച്ചു വന്നില്ല. പിന്നേം വിളിച്ചു വന്നില്ല. പിന്നേം വിളിച്ചപ്പോഴാണ് സാധനം വന്നത്,  കാരണം എന്ത്?', 'കാരണം അത് ചാർകോൾ ചിക്കൻ ആയിരുന്നു 
