INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('LYFcoNbt6Ow86i0AgOfb', 'qna', 'ഒരാള്‍ ഒരു ദ്വീപില്‍ കുടുങ്ങി നില്‍ക്കുകയാണ്.  അവിടെ മറ്റൊന്നുമില്ല. പക്ഷെ അയാളുടെ കൈയില്‍ ആകെ ഒരു കത്തിയുണ്ട്. അയാൾ അവിടെ നിന്ന് എങ്ങനെ രക്ഷപ്പെടും?', 'കത്തി വച്ച് കൈയില്‍ മുറിവുണ്ടാക്കുക. അപ്പോള്‍ കൈയില്‍ നിന്ന് ചോര താഴെ മണ്ണില്‍ വീഴും. അപ്പോള്‍ ചോര വീണ മണ്ണില്‍ നിന്ന് പൂമരം ഉയർന്ന്  വരും. ആ പൂമരം കൊണ്ട് കപ്പല്‍ ഉണ്ടാക്കി അതില്‍ കേറി രക്ഷപ്പെടും.', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788601794441, 1788601794441);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('LYFvxOzQ8W5LdAb6yQxS', 'qna', 'ഒരു അമ്മുമ്മ പല്ല് തേച്ചു കൊണ്ട് നിക്കുവായിരുന്നു. പെട്ടന്ന് അവര് മരിച്ചു. എങ്ങനെ?', 'അമ്മുമ്മ Colgate ഇട്ട പല്ല് തേച്ചത്. കേട്ടിട്ടില്ലേ ''Colgate max fresh.. വായിൽ ഉന്മേഷത്തിന്റെ അമിട്ട് പൊട്ടി ''', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788690438/malayalam-joke-app/krlakljrnfprjsmlpzes.png', 'malayalam-joke-app/krlakljrnfprjsmlpzes', 5, 0, 'deleted', 'anonymous', NULL, 1788690439943, 1788690439943);
