INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('NFw7rzuRnWMHc5x6uwU7', 'qna', 'രണ്ടാൾക്കാർ കപ്പലിൽ പോകുമ്പോൾ കടലിന്റെ നടുക്ക് അകപ്പെട്ടുപോയി. അവരുടെ കയ്യിൽ ആകെക്കൂടി ഒരു തോക്ക് മാത്രമാണുള്ളത്. വിശന്നു വലഞ്ഞ അവർ ആകെ വിഷമത്തിലായി. അവർ എന്ത് ചെയ്യും?', 'ഒരാൾ തോക്കെടുത്ത് മറ്റേ ആളുടെ പുറത്തേക്ക് വെടിവെക്കും. അപ്പോൾ പുറം ഓട്ടയാകും (പൊറോട്ടയാകും). രണ്ടാമതും വെടിവെക്കും, അപ്പോൾ വെടി കൊള്ളില്ല ,ചാറ് ആകും , അങ്ങനെ പൊറോട്ടയും ചാറും കൂട്ടി രണ്ടാളും കഴിക്കും!', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788458135/malayalam-joke-app/tbde0wucpewymnnmitze.jpg', 'malayalam-joke-app/tbde0wucpewymnnmitze', 63, 60, 'active', 'anonymous', 0.49132691822236330, 1788458136545, 1788458136545);
