INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('NN4xExHwE7GIzKuZknGk', 'qna', 'ഒരാൾ ഒരു ദ്വീപിൽ പെട്ടുപോയി. അയാളുടെ കൈവശം ഒരു ബ്ലേഡ് മാത്രമേയുള്ളൂ. അയാൾ എങ്ങനെയാണ് അവിടെ നിന്ന് രക്ഷപ്പെടുക?', 'അയാൾ ബ്ലേഡ് കൊണ്ട് കൈയിൽ മുറിവുണ്ടാക്കി രക്തം മണ്ണിലേക്ക് ഒഴിക്കും. “ചോര വീണ മണ്ണിൽ നിന്ന് ഉയിർന്ന പൂമരം…” — ആ പാട്ടിൽ പറയുന്നതുപോലെ അവിടെ ഒരു പൂമരം ഉയർന്നുവരും. "ആ പൂമരം കൊണ്ട് കപ്പലുണ്ടാക്കി", അതിൽ കയറി ദ്വീപിൽ നിന്ന് രക്ഷപ്പെടും! 😂🚢🌳(2 song references)', NULL, NULL, 5, 0, 'deleted', 'anonymous', NULL, 1788501956474, 1788501956474);
