INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('RrcGTphM7vmR8WM7ptlz', 'qna', 'റൂം A യിലെ പയ്യൻ, റൂം B യിലെ പെണ്ണിൻറെ കയ്യിൽ തന്റെ റൂമിന്റെ Key ഏൽപ്പിച്ചു പുറത്തേക്ക് പോയി. പയ്യൻ തിരിച്ചുവന്ന് റൂം B യുടെ പുറത്തുനിന്ന് ഒരു പാട്ടുപാടി. അപ്പോൾ ആ പെൺകുട്ടി വാതിൽ തുറന്ന് Key കൈമാറി. ഏതായിരിക്കും ആ പാട്ട്?', 'എൻറെ കിത്താബിലെ (key താ B യിലെ) പെണ്ണേ.', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788488098020, 1788488098020);
