INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('W8V6fpKz5TLvvP5N9Y5C', 'qna', 'കാട്ടില്ലേ എല്ലാം മൃഗങ്ങളും Facebook Account എടുത്തു..അട്ട മാത്രം എടുത്തില്ല.. Why?', 'അട്ടയെ പിടിച്ചു Meta യിൽ കിടത്തിയ കിടക്കില്ല', NULL, NULL, 208, 50, 'active', 'admin', 0.20248288145437643, 1785081212594, 1785081212594);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('W8rHoJYIsDFhNtVVWS0Y', 'qna', 'ഒരാൾക്ക് കുളിക്കണം, പക്ഷേ വെള്ളം ഇല്ല. അയാളുടെ കയ്യിൽ ആകെയുള്ളത് പായസവും ഉപ്പും. എങ്ങനെ കുളിക്കും?', 'അയാള് ആ ഉപ്പ് എടുത്ത്  പായസത്തിൽ ഇടും, അപ്പോൾ അത് കുളമാകും. ആ കുളത്തിൽ ഇറങ്ങി കുളിക്കും.', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788586784394, 1788586784394);
