INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('as0MDRpTIHvRWYG8YE7r', 'qna', 'പുസ്തകം എന്തിനാ കരഞ്ഞത്?', 'അതിന്റെ പേജ് കീറിയതുകൊണ്ട്!', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788545786/malayalam-joke-app/v6xqgnioakkb58sf3eov.jpg', 'malayalam-joke-app/v6xqgnioakkb58sf3eov', 5, 0, 'quarantine', 'anonymous', NULL, 1788545788058, 1788545788058);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('asWj4gpqTg3oCsPZWtxm', 'qna', 'ഒരു നമ്പൂതിരി എല്ലാ ദിവസവും കുളിക്കാനായ് ഒരു കുളത്തിൽ പോകുമായിരുന്നു ആ കുളത്തിന്റെ കരയിലായ് ഒരു മാവ് ഉണ്ട് അതിൽ 100 മാങ്ങയും അയാൾ കുളിക്കാൻ പോകുമ്പോ ഒന്ന് വീണു തിരിച്ചു വരുമ്പോഴും ഒന്ന് വീണു പക്ഷെ ആ മരത്തിൽ മാങ്ങയുടെ എണ്ണം ഒന്ന് പോലും കുറഞ്ഞില്ല. എന്തുകൊണ്ട്?', 'കാരണം കുളിക്കാൻ പോകുമ്പോഴും വരുമ്പോഴും വീണത് നമ്പൂതിരി ആയിരുന്നു. 😌', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788463441/malayalam-joke-app/cro6oyi7mj2dblugmhmf.jpg', 'malayalam-joke-app/cro6oyi7mj2dblugmhmf', 97, 59, 'active', 'anonymous', 0.50352433062236546, 1788463442930, 1788463442930);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('at2sP2wDRbyxGtHXURaL', 'qna', 'തൂറാത്തവൻ തൂറുമ്പോൾ എന്ത് സംഭവിക്കും?', 'തീട്ടം കൊണ്ട് ആറാടും', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788758053/malayalam-joke-app/m5imds5mzwq0bcuapwax.jpg', 'malayalam-joke-app/m5imds5mzwq0bcuapwax', 5, 0, 'deleted', 'anonymous', NULL, 1788758054576, 1788758054576);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('atIitB2DNqbtqu1uYAX1', 'qna', 'ചോദ്യം: ലോകത്ത് ഏറ്റവും കൂടുതൽ പണമുള്ള പക്ഷി ഏതാണ്?', 'ഉത്തരം: കാക്ക (കാരണം അത് ''Crow-re-pati'' (ക്രോർപതി) ആണല്ലോ!).', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1789281701/malayalam-joke-app/f8kkomxsoao24ucsfzom.jpg', 'malayalam-joke-app/f8kkomxsoao24ucsfzom', 5, 0, 'quarantine', 'anonymous', NULL, 1789281702257, 1789281702257);
