INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('bDTRJgbX5sMdFWiLnXdi', 'qna', 'റൊണാൾഡോയും മെസ്സിയും ഒരു മരുഭൂമിയിൽ ഫുട്ബോൾ കളിക്കുകയായിരുന്നു. പെട്ടെന്നു റൊണാൾഡോയ്ക്കു പരിക്ക് പറ്റി. മെസ്സി എന്ത് ചെയ്യും??? (വേറെ ആരും തന്നെ അവിടെ ഇല്ല)', 'മെസ്സി കുറച്ചു ദൂരെ മാറി നില്കും. അപ്പോൾ far messi ആകും (pharmacy). അവിടുന്നു മരുന്ന് എടുത്ത് വെക്കും. 👀', NULL, NULL, 5, 0, 'deleted', 'anonymous', NULL, 1788458893838, 1788458893838);
