INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('bFKWUkarxs96f4s74ZYT', 'qna', 'ഒരു ദിവസം രാമു മരുഭൂമിയിൽ നടക്കുക അയാരിരുന്നു അപ്പോൾ അവൻ വിയർത്തു അവന്റെ കൈയിൽ ഒരു തോക്ക് മാത്രം ഒള്ളു തൂടക്കാൻ അവൻ എന്ത് ചെയ്യും?', 'ആ തോക്ക് കൊണ്ട് വെടിവെക്കും എന്നിട്ട്  ട്ടിശൂ ട്ടിശൂ എന്ന് വെടി വെക്കും ആ ടിഷൂമ് വെച്ച് തുടക്ക്കും', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788686275/malayalam-joke-app/voif96fdwvzhkxgocnnl.jpg', 'malayalam-joke-app/voif96fdwvzhkxgocnnl', 5, 0, 'deleted', 'anonymous', NULL, 1788686277359, 1788686277359);
