INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('bFqHeFyPdMiKf0SEsYVj', 'qna', 'മൂന്ന്  ഫാർമർമാർ ഉണ്ട് Farmer A പാൽ ആണ് വിളിക്കുന്നത്, Farmer B ചോളം ആണ് വിളിക്കുന്നത്  എങ്കിൽ Farmer C എന്താണ് വിളിക്കുന്നത്', 'മരുന്ന്, Farmer C (ഫാർമസി )', NULL, NULL, 118, 62, 'active', 'anonymous', 0.04913807911792079, 1788458631347, 1788458631347);
