INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('bWmWkwqwoDyJbSY7175D', 'qna', 'ഒരു ആന ഒരുമ്പിനെ ഓടിച്ചിട്ട്‌ എന്നിട്ട് ഒരുമ്പേ ഓടി പള്ളിയിൽ കേറി പക്ഷെ ആന കണ്ടുപിടിച്ചു കാരണം എന്തെ', 'കാരണം ഉറുമ്പ്  പള്ളിയിൽ കേറിയപ്പോൾ ചെരിപ്പ് ഊരിയിട്ടാണ് keriyathe', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788970445029, 1788970445029);
