INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('bYMyfsuxro61NiQeNl1z', 'qna', 'ഒരാൾ ഒരു ഒറ്റപ്പെട്ട കടൽ തീരത്ത് പെട്ടു അയാൾ എങ്ങനെ രക്ഷപ്പെടും ?, ആ കടൽ തീരത്ത് മരങ്ങളൊന്നും ഇല്ല. അയാളുടെ കൈയിൽ ഒരു കത്തി മാത്രം ഉണ്ട്.', 'അയാൾ കത്തിയെടുത്ത് കൈമുറിക്കും ആ ചോര മണ്ണിൽ വീഴും അപ്പോൾ,  "ചോരവീണ മണ്ണിൽ നിന്നുയർ ന്നുവന്ന പൂമരം"ആ പൂമരം കൊണ്ട് അയാൾ കപ്പൽ ഉണ്ടാക്കി രക്ഷപ്പെടും', NULL, NULL, 5, 0, 'deleted', 'anonymous', NULL, 1788683618878, 1788683618878);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('baVcMFPgp7jfL12L9bov', 'qna', 'ഒരു കിളി പറന്നു പോവുമ്പോൾ മുട്ട ഇട്ടു അത് പൊട്ടീല്ല എന്ത് കൊണ്ട്', 'കിളി ഷഡ്ഢി ഇട്ടിട്ടുണ്ടായിരുന്നു', NULL, NULL, 158, 36, 'active', 'anonymous', 0.03111381198676255, 1788445004660, 1788445004660);
