INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('feYOpBF0CVxFEjlnT5m6', 'qna', 'കാട്ടിൽ വെച്ച് ഒരു കടുവ ടാറ്റുമോളുടെ നേരെ ചാടിവീണു. ടാറ്റുമോൾ ഓടാതെ കടുവയ്ക്ക് 2000 രൂപയുടെ നോട്ട് കൊടുത്തു. കടുവ ഉടനെ ഓടിപ്പോയി... എന്തുകൊണ്ട്?', 'കാരണം കടുവയ്ക്ക് മനസ്സിലായി ടാറ്റുമോൾ ഒരു ''ചില്ലറക്കാരി'' അല്ല എന്ന്🫣', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788520154288, 1788520154288);
