INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('ff8DagEXwTQAloBCCZ8m', 'qna', 'ഒരു മൂന്ന് സ്ത്രീകൾ ഐസ് ക്രീം പാർലറിൽ പോയി ഐസ് ക്രീം വാങ്ങി ഒരാൾ അത് കടിച്ചു തിന്നുന്നു, ഒരാൾ വായിൽ വെക്കുന്നു , ഒരാൾ നക്കുന്നു ചോദ്യമെന്തെന്നാൽ അതിൽ ആരാണ് കല്യാണം കഴിച്ചത്??', 'അതിൽ കല്യാണം മോതിരം മോതിരം ഉള്ള ആളാണ് കല്യാണം കഴിച്ചത്', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788452895/malayalam-joke-app/j1pkr3sxuzlacmjqjnft.jpg', 'malayalam-joke-app/j1pkr3sxuzlacmjqjnft', 56, 53, 'active', 'anonymous', 0.91673951707056656, 1788452896607, 1788452896607);
