INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('gbl0dDOD791DXuQfpMmX', 'qna', 'ആമയും മുയലും ഓട്ടമത്സരം വെച്ചപ്പോൾ ശെരിക്കും മുയലാണ് ജയിച്ചത് പക്ഷെ സമ്മാനം ആമക്ക് കൊടുത്തു. എന്തുകൊണ്ട്?', 'മത്സരം നിയന്ത്രിച്ച തമിഴൻ റെഫറിയോട് മുയൽ ആണോ ജയിച്ചത് എന്ന് ചോദിച്ചപ്പോൾ “ആമ” എന്നാണ് പറഞ്ഞത്', NULL, NULL, 5, 0, 'deleted', 'anonymous', NULL, 1788679646674, 1788679646674);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('gbrFW2ZX3gb068gFNBzf', 'qna', 'ഒരാൾ കാട്ടിൽ ഒറ്റപ്പെട്ടു പോയി, അയാൾക്ക് അടിയന്തരമായി എറണാകുളത്ത് എത്തണം. കയ്യിൽ കുറച്ച് വെളുത്ത പെയിന്റ് (White paint) മാത്രമേ ഉള്ളൂ. അയാൾ എന്ത് ചെയ്യും?', 'അയാൾ ആ പെയിന്റ് എടുത്ത് ഒരു ഇലയിൽ അടിക്കും... അപ്പോൾ അത് ''വൈറ്റ് ഇല'' (Vyttila) ആകും!', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788519910556, 1788519910556);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('geP1lzQ7BOqL0ryTnufo', 'qna', 'ഒരു ഉറുമ്പും ഒരു തിമിംഗലവും കൂടെ അടി കൂടുകയായിരുന്നു. അതിൽ ഉറുമ്പ് ജയിച്ചു. എങ്ങനെ ??', 'ഉറുമ്പ് sunscreen തേച്ചിട്ടുണ്ടായിരുന്നു. അപ്പൊ വെയിൽ അടിച്ചാൽ ഒന്നും പറ്റില്ല.', NULL, NULL, 164, 88, 'active', 'admin', 0.89372483158207483, 1785132447819, 1785132447819);
