INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('gvCUbHXzc3PlF3bXRAN3', 'qna', 'ഒരാൾ ഒരു ഒന്നുമില്ലാത്ത ഒരു ദ്വീപിൽ കുടുങ്ങി അയാളുടെ കയ്യിൽ ആകെ ഉള്ളത് ഒരു കത്തി മാത്രമാണ്.അയാൾ അവിടെ നിന്ന് എങ്ങനെ രക്ഷപെടും?', 'അയാൾ കത്തികൊണ്ട് മുറിവേൽപ്പിക്കും അപ്പോൾ ചോര വരും. ചോര വീണ മണ്ണിൽ നിന്ന് ഉയർന്ന് വന്ന പൂമരം ആ പൂമരം കൊണ്ട് കപ്പലുണ്ടാക്കി 😌 അതിൽ കേറി രക്ഷപ്പെടും', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1789203720/malayalam-joke-app/qyciapmb43hommkyrpcr.jpg', 'malayalam-joke-app/qyciapmb43hommkyrpcr', 5, 0, 'quarantine', 'anonymous', NULL, 1789203721888, 1789203721888);
