INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('iS0AfxWBu5QqJJGGQP0U', 'qna', 'ഒരാൾ ഒരു പാറ്റയുടെ കൂടെ our ബോട്ടിൽ ഇരിക്കുകയായിരുന്നു. അയാൾ പാട്ട് പാടിയപ്പോൾ ആ പാറ്റ ചത്ത് പോയി. എന്തുകൊണ്ട്?', 'കാരണം അയാള് പൂമരം സോങ് ആണ് പാടിയത്. ആ പാട്ട് വളരെ ഹിറ്റ് ആയിരുന്നു. ആ ഹിറ്റ് കാരണം പാറ്റ ചത്തു.', NULL, NULL, 7, 5, 'deleted', 'admin', NULL, 1785133951319, 1785133951319);
