INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('kEolq6V2IlpGcsq7pJnl', 'qna', 'ഒരു ബ്ലൂവെയിലും(🐳) ഒരു ഉറുമ്പും(🐜 )തമ്മിൽ അടിയുണ്ടായി. പക്ഷെ ഉറുമ്പ് ചത്തില്ല. കാരണം?😌', 'കാരണം ഉറുമ്പ് sunscreen ഇട്ടിരുന്നു.so വെയിൽ അടിച്ചപ്പോ sun protection ആയി .🙂🧑🏻‍🦯', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788486549679, 1788486549679);
INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('kFGGZOHgU2GqiMKVW3Da', 'qna', 'ഒരാള്‍ ഒരു മരുഭൂമിയില്‍ കുറെ മുള്ള് ചെടികളുടെ നടുക്ക് കുടുങ്ങി. അയാളുടെ കൈയില്‍ കുറച്ചധികം മദ്യം ഉണ്ട് ,അയാൾ ഇങ്ങനെ മുള്ള് ചെടികളില്‍ നിന്ന് രക്ഷപ്പെടും?', 'അയാള്‍ മദ്യം കുടിച്ച് വാള്‍ വെക്കും, എന്നിട്ട്‌ ആ വാള്‍ വെച്ച് മുള്ള് ചെടി വെട്ടി മുറിച്ച് രക്ഷപ്പെടും.', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788612456/malayalam-joke-app/bylfulfvbhjsqqumzs72.png', 'malayalam-joke-app/bylfulfvbhjsqqumzs72', 5, 0, 'quarantine', 'anonymous', NULL, 1788612459564, 1788612459564);
