INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('lQwuUCJseIlbVzcniLBh', 'qna', 'ഒരിക്കൽ ഒരു യുവാവ് വഴിയിലൂടെ പോവുമ്പോൾ പെട്ടെന്ന് ഒരു പുലി മുന്നിലേക്ക് ചാടി..!!പേടിച്ചു പോയ അദ്ദേഹം കയ്യിൽ ഉണ്ടായിരുന്ന കുറച്ചു നോട്ടുകെട്ടുകൾ എടുത്തു പുലിക്ക് നേരെ വീശി. പുലി ഓടി തള്ളി! Why.??', 'പുലിക്ക് മനസിലായി അദ്ദേഹം "ചില്ലറക്കാരൻ" അല്ലെന്ന് (നോട്ട് അല്ലെ വീശിയത് )', NULL, NULL, 5, 0, 'deleted', 'anonymous', NULL, 1788501782083, 1788501782083);
