INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('nZ4TO4E5iSIhaiBX3SIZ', 'qna', 'കട്ടപ്പനും കുട്ടപ്പനും ഒരിക്കൽ ഒരു പുഴയുടെ അരികിൽ പോവുക ആയിരുന്നു വലത് പുഴ ആണെങ്കിൽ ഇടത് കാട് അപ്പൊ കാട്ടിൽ നിന്ന് ഒരു വരയൻ പുലി അവരെ ആക്രമിക്കാൻ വന്നു കുട്ടപ്പൻ ഓടാൻ അറിയുന്നത് കൊണ്ട് അവൻ ഓടി നക്ഷപെട്ടു കട്ടപ്പൻ ഓടാനും നീന്താനും ഉള്ള കഴിവ് ഇല്ല എപ്പോൾ എങ്ങനെ കട്ടപ്പൻ വരയൻ പുലിയിൽ നിന്ന് രക്ഷപ്പെടും', 'പുഴയിൽ നിന്ന് കുളിച്ച് കുട്ടപ്പൻ ആയി രക്ഷപ്പെടും 🙂', 'https://res.cloudinary.com/ikrkjuoq/image/upload/v1788668393/malayalam-joke-app/r9fwhrg6pbr2ylfqvbxk.jpg', 'malayalam-joke-app/r9fwhrg6pbr2ylfqvbxk', 5, 0, 'deleted', 'anonymous', NULL, 1788668394194, 1788668394194);
