INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('p1gW8MyAPD69hAsCWxNG', 'qna', 'കട്ടപ്പനും കുട്ടപ്പനും കാട്ടിൽ പോയി.അവർ ഒരു കുളത്തിൻ്റെ അടുത്ത് എത്തിയപ്പോൾ ഒരു കരടി വന്നു.കുട്ടപ്പൻ നീന്താൻ അറിയാം കട്ടപ്പൻ നീന്താൻ അറിയില്ല. കുട്ടപ്പൻ നീന്തി പോയി കട്ടപ്പൻ എന്ത് ചെയ്യും', 'കട്ടപ്പൻ വെള്ളത്തിൽ ഇറങ്ങിയാൽ കുട്ടപ്പൻ ആകും അങ്ങനെ അവനും നീന്തി പോകും', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1789229078409, 1789229078409);
