INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('rirvLBvPklYAhLrkeDhO', 'qna', 'ഒരാൾ മരുഭൂമിയിൽ ഒറ്റപ്പെട്ടുപോയി. കൈയിൽ ഒരേയൊരു ടോയ് (Toy) മാത്രം. അവിടുന്ന് എങ്ങനെ രക്ഷപ്പെടും?', 'അതിലൊരു ഓട്ട ഉണ്ടാക്കും... അത് Toyota ആകും, അതിൽ കയറി രക്ഷപ്പെടും!', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788549625035, 1788549625035);
