INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('rnrW49f7xds7cjO7B5oh', 'qna', 'ഒരാൾ മന്ത്രിയെ കാണാൻ ഓഫീസിൽ പോയി. പക്ഷേ മന്ത്രി അവിടെ ഇല്ലായിരുന്നു. Whyy?', 'കാരണം മന്ത്രി ഹോം മിനിസ്റ്റർ ആയിരുന്നു.', NULL, NULL, 10, 11, 'quarantine', 'admin', NULL, 1785223723672, 1785223723672);
