INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('t7hbDXC2Ir8YH7H90s81', 'qna', 'പ്രതികളായ തങ്കപ്പനെയും കുട്ടപ്പനെയും പോലീസ് പിടികൂടി. അടുത്ത ദിവസം കോടതിയിൽ ഹാജരാക്കേണ്ട ഇരുവരെയും പോലീസ് രാത്രി ജയിലിലടച്ചു. എന്നാൽ അന്നുരാത്രി കുട്ടപ്പൻ ജയിൽ ചാടി. എന്നിട്ടും പിറ്റേന്ന് പോലീസ് കുട്ടപ്പനെ കോടതിയിൽ ഹാജരാക്കി. എങ്ങനെ?', 'കയ്യിലുണ്ടായിരുന്ന പ്രതിയായ തങ്കപ്പനെ പോലീസ് കുളിച്ച് കുട്ടപ്പനാക്കി!', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788518377441, 1788518377441);
