INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('u5sPowrsqmNNDYT0Su8D', 'single', 'Teacher: നിനക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ട subject ഏതാണ്? Student: Subject അല്ല ടീച്ചർ… object ആണ്! Teacher: അതെന്താ? 🤨 Student: നിങ്ങളെ കണ്ടാൽ എന്റെ ഹൃദയം തന്നെ object ആയി മാറും… കാരണം നിങ്ങൾ എന്റെ heart object ആണല്ലോ! 😭😂
Teacher: പുറത്തേക്ക് പോ! Student: പുറത്തേക്ക് പോയാലും ഞാൻ നിങ്ങളുടെ class വിട്ട് പോകില്ല… കാരണം നിങ്ങൾ എന്റെ classmate അല്ല, class-mate ആണ്! 🤣🤣
Teacher: 😑 Student: ടീച്ചർ, ഈ ചളിക്ക് മാർക്ക് എത്ര? Teacher: Zero. Student: അപ്പോൾ ഞാൻ zero gravity പോലെ പറന്നുപോകട്ടെ! 🛸😂', NULL, NULL, NULL, 5, 0, 'deleted', 'anonymous', NULL, 1788888596500, 1788888596500);
