INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('uoL2Hl6Q3DsNxxVgl2VB', 'qna', 'കൊച്ചാപ്പി കാട്ടിലൂടെ പോവുകയായിരുന്നു, പെട്ടെന്നതാ  മുന്നിൽ ഒരു പുലി. കൊച്ചാപ്പി പോക്കറ്റിൽ നിന്ന് ഒരു 2000 രൂപ നോട്ട് എടുത്ത് പുലിയുടേനേരെ വിശി, അപ്പോൾ പുലി പേടിച്ച് ഓടിപ്പോയി. എന്തുകൊണ്ട്???', 'പുലിക്കു മനസ്സിലായി കൊച്ചാപ്പി  ചില്ലറക്കാരനല്ല എന്ന്.', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788551392609, 1788551392609);
