INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('v1O6JdbHgJj6BGFKVIBw', 'qna', 'ഒരു ബസ് സ്റ്റോപ്പ്‌. ഒരു പ്രായമുള്ള സ്ത്രീ ബസിൽ കേറുമ്പോൾ കണ്ടക്ടർ ബെൽ അടിച്ചു. ആ സ്ത്രീ റോഡിൽ വീണു മരിച്ചു. കുറ്റക്കാരനായ കണ്ടക്ടറെ ഷോക്ക് അടിപ്പിച്ചു കൊല്ലാൻ കോടതി വിധിച്ചു. പക്ഷെ ഷോക്ക് അടിപ്പിച്ചു കൊല്ലാൻ പറ്റിയില്ല. എന്തുകൊണ്ട്?', 'കാരണം കണ്ടക്ടർ ഒരു Bad conductor ആരുന്നു.', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1789304040981, 1789304040981);
