INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('w4iUlQuXFMxE2LIriBFF', 'single', 'ഞങ്ങളുടെ നാട്ടിലൊക്കെ തേങ്ങാ പൊതിക്കുന്ന എങ്ങനാണെന്നു വെച്ചാൽ, ആദ്യം തേങ്ങാ എല്ലാം ഞങ്ങൾ കവലയിൽ കൊണ്ടുപോയി കൂട്ടിയിടും. എന്നിട്ട് നാട്ടുകാരെ ഒക്കെ വിളിച്ചു കൂട്ടിയിട്ട് തെങ്ങയെ തെറിവിളിക്കും. അപ്പൊ നാണം കാരണം തേങ്ങയുടെ തൊലി ഉരിഞ്ഞു പോരും.', NULL, NULL, NULL, 12, 12, 'quarantine', 'admin', NULL, 1785071515832, 1785071515832);
