INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('w8FEcGCExdx69WZKZEkK', 'qna', 'ഒരു അറബി മരുഭൂമിയിലൂടെ നടക്കുകയായിരുന്നു. അയാളുടെ കയ്യിൽ ആകെ ഒരു തോക്ക് മാത്രമേ ഉള്ളു. ചൂട് കാരണം അയാളുടെ മുഖം ഒക്കെ വിയർക്കാൻ തുടങ്ങി. അപ്പോൾ അയാൾ എന്ത് ചെയ്യും?', 'ആ തോക്ക് എടുത്തു " ടിഷ്യൂ " ന്ന് വെടി വെക്കും. എന്നിട്ട് ആ ടിഷ്യൂ എടുത്തു മുഖം തുടയ്ക്കും', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788587186276, 1788587186276);
