INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('zcSwaSd0AH64WDhzhaX6', 'qna', 'ഒരാൾ മരുഭൂമിയിൽ നിൽക്കുകയാണ് അയാൾക് വിയർക്കാൻ തുടങ്ങി കൈയിൽ ഒരു തോക്കുണ്ട്,  അപ്പോൾ എങ്ങനെ തന്റെ വിയർപ്പ് അയാൾ തുടച്ചുകളയും?', 'തോക്ക് കൊണ്ട് മേളിലൊട്ടു വെടി വെയ്ക്കും അപ്പൊ, tissue tissue എന്നു ഒച്ച വരും ആ tissue എടുത്ത് മുഖം തുറക്കും', NULL, NULL, 5, 0, 'quarantine', 'anonymous', NULL, 1788520201092, 1788520201092);
