INSERT OR IGNORE INTO jokes (id, type, question, answer, image_url, image_public_id, upvotes, downvotes, status, submitted_by, rand, timestamp, created_at) VALUES ('zhBlZKkUoKnZOYQXwAAX', 'qna', 'അച്ഛൻ മകനെ സ്കൂളിൽ കൊണ്ടുപോവുകയായിരുന്നു. എത്തിക്കാൻ വണ്ടിയില്ല. അഞ്ചോ ആറോ കുന്നുകൾ കയറിയിറങ്ങി വേണം സ്കൂളിൽ എത്താൻ. അന്ന് അവർ ഇറങ്ങാൻ Late ആയി. സമയത്തു എത്തില്ല എന്ന് ഉറപ്പു. രണ്ടാമത്തെ കുന്നിന്റെ ഇറക്കത്തിൽ ഒരാൾ വണ്ടി ഒതുക്കി നിർത്തി ഐസ് ക്രീം വിൽക്കുന്നുണ്ടായിരുന്നു. അച്ഛന് അവനെ Bell അടിക്കുമ്പോൾ തന്നെ സ്കൂളിൽ എത്തിക്കാൻ സാധിച്ചു. എങ്ങനെ?', 'അച്ഛൻ മോന് ഒരു Ice Cream വാങ്ങിച്ചു കൊടുത്തു. അപ്പോൾ ആ മോൻ santhoshaVAN ആയി. ആ വാനിൽ അച്ഛൻ മകനെ സ്‌കൂളിൽ എത്തിച്ചു.  😁', NULL, NULL, 135, 82, 'active', 'admin', 0.58212382279391073, 1785134142812, 1785134142812);
